<?php
namespace Tests\Feature\Finance;
use App\Models\{CmsUser,CmsCountry,CmsUserType,WalletAccount,WalletLedgerEntry,CmsUserTransaction,FinanceManualOverride,CmsPromotionCode,InternalGameRound,InternalGameSession};
use App\Services\Wallet\{AssetWalletService,SpendableWalletService,CanonicalWalletService,ActiveWalletService};
use App\Services\Finance\ManualFinanceOverrideService;
use App\Services\InternalGames\{DiceService,DiceEngine,InternalGameSessionService,InternalGameLedgerAuditService,InternalGamePlayService,RouletteService,RouletteOutcomeResolver};
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\{DB,Hash,Http,Schema};
use Illuminate\Http\Request;
use Tests\TestCase;
class CanonicalFinanceGamesTest extends TestCase {
 use DatabaseTransactions;
 private CmsUser $user;private CmsUser $admin;private WalletAccount $wallet;
 protected function setUp(): void {parent::setUp();Http::preventStrayRequests();(new \Database\Seeders\InternalDiceDemoSeeder)->run();(new \Database\Seeders\InternalRouletteSeeder)->run();$this->admin=CmsUser::where('role','admin')->firstOrFail();$this->user=CmsUser::create(['username'=>'finance_owner','email'=>'finance-owner@example.invalid','role'=>'customer','status'=>'normal','country_id'=>CmsCountry::value('id'),'user_type_id'=>CmsUserType::value('id'),'currency'=>'TRY','password'=>Hash::make('Finance-Local-927!')]);$this->wallet=DB::transaction(fn()=>app(AssetWalletService::class)->ensurePrimaryBalanceWallet($this->user,'TRY',true));$store=app('session')->driver();$store->start();$request=Request::create('/cms/games/dice/launch');$request->setLaravelSession($store);$this->app->instance('request',$request);}
 private function intent(string $key='fund-first',string $action='manual_credit',string $amount='100.00'): array {return ['operation_id'=>$key,'customer_id'=>$this->user->id,'wallet_account_id'=>$this->wallet->id,'currency'=>'TRY','economic_action'=>$action,'external_resolution'=>'manual_operator_decision','amount'=>$amount,'reason'=>'Synthetic local acceptance','evidence_reference'=>'local-fixture'];}
 private function fund(string $amount='100.00'):array {return app(ManualFinanceOverrideService::class)->execute($this->intent('fund-first','manual_credit',$amount),$this->admin);}
 private function openGameSession(string $slug='dice',bool $demo=false):InternalGameSession{return app(InternalGameSessionService::class)->launch(\App\Models\CmsGame::where('slug',$slug)->firstOrFail(),$this->user,$demo,request());}
 private function reconcile():void{$this->wallet->refresh();$sum=DB::table('wallet_ledger_entries')->where('wallet_account_id',$this->wallet->id)->selectRaw("COALESCE(SUM(CASE direction WHEN 'credit' THEN amount ELSE -amount END),0) n")->value('n');$this->assertTrue(\Brick\Math\BigDecimal::of((string)$sum)->isEqualTo((string)$this->wallet->available_balance));$this->assertTrue(\Brick\Math\BigDecimal::of((string)$this->user->fresh()->balance)->isEqualTo((string)$this->wallet->available_balance));}
 private function reject(callable $fn):void{try{$fn();$this->fail('Expected rejection');}catch(\App\Services\Wallet\Exceptions\UnsupportedProductWalletException|\DomainException|\Symfony\Component\HttpKernel\Exception\HttpException $e){$this->assertNotEmpty($e->getMessage()?:get_class($e));}}
 public function test_manual_credit_debit_replay_conflict_and_no_negative_balance():void{$r=$this->fund();$this->assertFalse($r['idempotent_replay']);$replay=app(ManualFinanceOverrideService::class)->execute($this->intent(),$this->admin);$this->assertTrue($replay['idempotent_replay']);app(ManualFinanceOverrideService::class)->execute($this->intent('debit-one','manual_debit','12.34'),$this->admin);$this->assertSame('87.66000000',$this->wallet->fresh()->available_balance);$this->reject(fn()=>app(ManualFinanceOverrideService::class)->execute($this->intent('fund-first','manual_credit','101.00'),$this->admin));$this->reject(fn()=>app(ManualFinanceOverrideService::class)->execute($this->intent('too-large','manual_debit','999.00'),$this->admin));$this->assertSame(2,FinanceManualOverride::count());$this->assertSame(2,WalletLedgerEntry::count());$this->reconcile();}
 public function test_customer_and_foreign_wallet_cannot_manual_credit():void{$this->reject(fn()=>app(ManualFinanceOverrideService::class)->execute($this->intent(),$this->user));$other=$this->user->replicate();$other->username='other';$other->email='other@example.invalid';$other->save();$foreign=DB::transaction(fn()=>app(AssetWalletService::class)->ensurePrimaryBalanceWallet($other,'TRY',true));$v=$this->intent();$v['wallet_account_id']=$foreign->id;$this->reject(fn()=>app(ManualFinanceOverrideService::class)->execute($v,$this->admin));$this->assertSame(0,WalletLedgerEntry::count());$this->assertSame(0,FinanceManualOverride::count());}
 public function test_real_dice_win_loss_linked_transactions_ledger_and_replay():void{$this->fund();$engine=\Mockery::mock(DiceEngine::class)->makePartial();$engine->shouldReceive('roll')->twice()->andReturn(9000,100);$this->app->instance(DiceEngine::class,$engine);$session=$this->openGameSession();$service=app(DiceService::class);$win=$service->roll($session->session_token,$this->user,20,'over',5000,'dice-real-win');$loss=$service->roll($session->session_token,$this->user,20,'over',5000,'dice-real-loss');$this->assertSame(0.39,$win['winAmount']);$this->assertSame(0.0,$loss['winAmount']);$this->assertSame($win,$service->roll($session->session_token,$this->user,20,'over',5000,'dice-real-win'));$this->assertSame(3,CmsUserTransaction::count());$this->assertSame(4,WalletLedgerEntry::count());$this->assertSame(2,InternalGameRound::count());$this->reconcile();}
 public function test_real_dice_loss_refund_once_and_winning_refund_rejection():void{$this->fund();$engine=\Mockery::mock(DiceEngine::class)->makePartial();$engine->shouldReceive('roll')->twice()->andReturn(1,9999);$this->app->instance(DiceEngine::class,$engine);$s=$this->openGameSession();$service=app(DiceService::class);$loss=$service->roll($s->session_token,$this->user,20,'over',5000,'refund-real-loss');$refund=app(InternalGamePlayService::class);$refund->refund($loss['roundId'],'refund-operation',$this->admin);$again=$refund->refund($loss['roundId'],'refund-operation',$this->admin);$this->assertSame('already_refunded',$again['result']);$win=$service->roll($s->session_token,$this->user,20,'over',5000,'refund-real-win');$this->reject(fn()=>$refund->refund($win['roundId'],'winning-refund-rejected',$this->admin));$this->assertSame(1,CmsUserTransaction::where('event_type','internal_dice_refund')->count());$this->reconcile();}
 public function test_unfunded_round_cannot_be_refunded():void{$this->fund();$s=$this->openGameSession();$r=InternalGameRound::create(['internal_game_session_id'=>$s->id,'provider_id'=>$s->provider_id,'cms_game_id'=>$s->cms_game_id,'cms_user_id'=>$s->cms_user_id,'root_user_id'=>$s->root_user_id,'is_demo'=>false,'game_code'=>'dice','round_id'=>'unfunded-round','session_public_id'=>$s->public_id,'currency'=>'TRY','status'=>'processing','bet_amount'=>'1.00','win_amount'=>0,'refund_amount'=>0,'request_ref'=>'unfunded-action','correlation_ref'=>(string)\Illuminate\Support\Str::uuid(),'raw_result'=>[],'result_summary'=>'Unfunded test fixture','started_at'=>now(),'settled_at'=>now()]);$this->reject(fn()=>app(InternalGamePlayService::class)->refund($r->round_id,'unfunded-refund',$this->admin));$this->assertSame(0,CmsUserTransaction::count());$this->reconcile();}
 public function test_dice_ledger_failure_rolls_back_debit_credit_round_and_balance():void{$this->fund();$s=$this->openGameSession();$audit=\Mockery::mock(InternalGameLedgerAuditService::class);$audit->shouldReceive('recordDecimal')->once()->andThrow(new \RuntimeException('Injected ledger failure'));$this->app->instance(InternalGameLedgerAuditService::class,$audit);try{app(DiceService::class)->roll($s->session_token,$this->user,20,'over',5000,'ledger-failure-round');$this->fail('Expected rollback');}catch(\RuntimeException $e){$this->assertSame('Injected ledger failure',$e->getMessage());}$this->assertSame(0,CmsUserTransaction::count());$this->assertSame(0,InternalGameRound::count());$this->assertSame('100.00000000',$this->wallet->fresh()->available_balance);$this->reconcile();}
 public function test_original_roulette_spin_lines_win_loss_replay_and_refund():void{$this->fund();$resolver=\Mockery::mock(RouletteOutcomeResolver::class);$resolver->shouldReceive('resolveWinningNumber')->twice()->andReturn(1,2);$this->app->instance(RouletteOutcomeResolver::class,$resolver);$s=$this->openGameSession('european-roulette');$service=app(RouletteService::class);$bets=[['betType'=>'straight','betKey'=>'1','stake'=>'1.00']];$win=$service->spin($s->session_token,$this->user,$bets,'roulette-win-key');$this->assertSame(36.0,$win['totalReturn']);$this->assertSame($win,$service->spin($s->session_token,$this->user,$bets,'roulette-win-key'));$loss=$service->spin($s->session_token,$this->user,$bets,'roulette-loss-key');$this->assertSame(0.0,$loss['totalReturn']);$service->refund($loss['roundId'],'roulette-refund-key',$this->admin);$again=$service->refund($loss['roundId'],'roulette-refund-key',$this->admin);$this->assertSame('already_refunded',$again['result']);$this->assertSame(2,\App\Models\InternalGameRoundBet::count());$this->reconcile();}
 public function test_demo_labeled_dice_and_roulette_use_canonical_finance():void{
  $this->fund();
  $dice=\Mockery::mock(DiceEngine::class)->makePartial();
  $dice->shouldReceive('roll')->once()->andReturn(1);
  $this->app->instance(DiceEngine::class,$dice);
  $roulette=\Mockery::mock(RouletteOutcomeResolver::class);
  $roulette->shouldReceive('resolveWinningNumber')->once()->andReturn(2);
  $this->app->instance(RouletteOutcomeResolver::class,$roulette);
  $d=$this->openGameSession('dice',true);
  app(DiceService::class)->roll($d->session_token,$this->user,20,'over',5000,'demo-labeled-dice');
  $r=$this->openGameSession('european-roulette',true);
  app(RouletteService::class)->spin($r->session_token,$this->user,[['betType'=>'straight','betKey'=>'1','stake'=>'1.00']],'demo-labeled-roulette');
  $this->assertFalse($d->is_demo);
  $this->assertFalse($r->is_demo);
  $this->assertSame('98.80000000',$this->wallet->fresh()->available_balance);
  $this->assertSame(2,CmsUserTransaction::count());
  $this->assertSame(3,WalletLedgerEntry::count());
  $this->reconcile();
 }
 public function test_write_gate_rejects_atomic_credit():void{DB::table('finance_reset_controls')->where('id',1)->update(['writes_closed'=>true]);try{$this->fund();$this->fail('Expected closed write gate');}catch(\RuntimeException $e){$this->assertSame('prelaunch_finance_writes_closed',$e->getMessage());}$this->assertSame(0,FinanceManualOverride::count());$this->assertSame(0,WalletLedgerEntry::count());}
 public function test_promo_credit_duplicate_expiry_and_atomic_ledger_rollback(): void {
  auth('cms')->setUser($this->user);$promo=CmsPromotionCode::create(['promo_code'=>'LOCAL-FINANCE','currency'=>'TRY','promo_amount'=>'10.25','promo_count'=>5,'promo_left'=>5,'status'=>'active']);
  $controller=app(\App\Http\Controllers\Cms\Front\PromotionCodeController::class);$req=Request::create('/cms/promotion-code/redeem','POST',['promoCode'=>'local-finance']);
  $this->assertSame(200,$controller->checkPromotionCode($req)->getData(true)['status']);$this->assertSame(400,$controller->checkPromotionCode($req)->getData(true)['status']);$this->assertSame(4,$promo->fresh()->promo_left);$this->assertSame(1,CmsUserTransaction::count());$this->assertSame(1,WalletLedgerEntry::count());$this->reconcile();
  $promo->update(['promo_code'=>'EXPIRED-FINANCE','end_date'=>now()->subMinute()]);$this->assertSame(400,$controller->checkPromotionCode(Request::create('/','POST',['promoCode'=>'EXPIRED-FINANCE']))->getData(true)['status']);
  $other=CmsPromotionCode::create(['promo_code'=>'ROLLBACK-PROMO','currency'=>'TRY','promo_amount'=>'1.00','promo_count'=>5,'promo_left'=>5,'status'=>'active']);
  $spend=\Mockery::mock(SpendableWalletService::class,[app(AssetWalletService::class),app(CanonicalWalletService::class)])->makePartial();$spend->shouldReceive('recordDecimalLedgerEntry')->once()->andThrow(new \RuntimeException('ledger rollback fixture'));$this->app->instance(SpendableWalletService::class,$spend);
  $this->assertSame(400,$controller->checkPromotionCode(Request::create('/','POST',['promoCode'=>'ROLLBACK-PROMO']))->getData(true)['status']);$this->assertSame(5,$other->fresh()->promo_left);$this->assertSame(1,CmsUserTransaction::count());$this->assertSame('10.25000000',$this->wallet->fresh()->available_balance);
 }
 public function test_original_roulette_large_canonical_balance_preserves_exact_cents(): void {
  $this->fund('90071992547410.29');$resolver=\Mockery::mock(RouletteOutcomeResolver::class);$resolver->shouldReceive('resolveWinningNumber')->twice()->andReturn(2,1);$this->app->instance(RouletteOutcomeResolver::class,$resolver);$session=$this->openGameSession('european-roulette');
  app(RouletteService::class)->spin($session->session_token,$this->user,[['betType'=>'straight','betKey'=>'1','stake'=>'1.00']],'large-balance-roulette');
  $this->assertSame('90071992547409.29000000',$this->wallet->fresh()->available_balance);$round=InternalGameRound::latest('id')->firstOrFail();app(RouletteService::class)->refund($round->round_id,'large-refund-key',$this->admin);$this->assertSame('90071992547410.29000000',$this->wallet->fresh()->available_balance);app(RouletteService::class)->spin($session->session_token,$this->user,[['betType'=>'straight','betKey'=>'1','stake'=>'1.00']],'large-win-roulette');$this->assertSame('90071992547445.29000000',$this->wallet->fresh()->available_balance);$this->reconcile();
 }
 public function test_multi_currency_selection_does_not_retarget_a_pinned_game_session(): void {
  $this->fund();$trySession=$this->openGameSession();$usd=DB::transaction(fn()=>app(AssetWalletService::class)->ensurePrimaryBalanceWallet($this->user,'USD',true));$intent=$this->intent('usd-local-credit','manual_credit','20.00');$intent['wallet_account_id']=$usd->id;$intent['currency']='USD';app(ManualFinanceOverrideService::class)->execute($intent,$this->admin);
  $this->assertSame('100.00000000',(string)$this->user->fresh()->balance);$result=DB::transaction(fn()=>app(ActiveWalletService::class)->switch($this->user,$usd->id));$this->assertSame(200,$result['status']);$usdSession=$this->openGameSession();$this->assertSame('USD',$usdSession->currency);$this->assertSame('TRY',$trySession->currency);
  app(DiceService::class)->roll($trySession->session_token,$this->user,20,'over',5000,'pinned-try-roll');$this->assertSame('20.00000000',$usd->fresh()->available_balance);
  $usd->update(['status'=>'passive']);$this->reject(fn()=>app(DiceService::class)->roll($usdSession->session_token,$this->user,20,'over',5000,'disabled-pinned-wallet'));$this->reconcile();
 }

 public function test_roulette_refund_rejects_borrowed_debit_without_finance_mutation(): void {
  $this->fund();$resolver=\Mockery::mock(RouletteOutcomeResolver::class);$resolver->shouldReceive('resolveWinningNumber')->twice()->andReturn(2,2);$this->app->instance(RouletteOutcomeResolver::class,$resolver);$session=$this->openGameSession('european-roulette');$service=app(RouletteService::class);$bets=[['betType'=>'straight','betKey'=>'1','stake'=>'1.00']];
  $one=$service->spin($session->session_token,$this->user,$bets,'refund-provenance-one');$two=$service->spin($session->session_token,$this->user,$bets,'refund-provenance-two');$r=InternalGameRound::where('round_id',$two['roundId'])->firstOrFail();$r->update(['debit_transaction_id'=>InternalGameRound::where('round_id',$one['roundId'])->value('debit_transaction_id')]);$before=$this->wallet->fresh()->available_balance;$count=WalletLedgerEntry::count();
  try{$service->refund($r->round_id,'forged-refund-rejected',$this->admin);$this->fail('Expected provenance rejection');}catch(\App\Exceptions\InternalGames\RouletteException $e){$this->assertSame('ROULETTE_REFUND_REJECTED',$e->errorCode());}
  $this->assertSame($before,$this->wallet->fresh()->available_balance);$this->assertSame($count,WalletLedgerEntry::count());$this->reconcile();
 }



}
